CAUTION_HTML = r'''
<dialog id="containment-caution" class="containment-caution" aria-labelledby="caution-title" aria-describedby="caution-effect caution-unknowns">
 <form method="dialog" id="caution-form"><header><p class="eyebrow">RESTRICTIVE ACTION / HUMAN CONFIRMATION</p><h2 id="caution-title" tabindex="-1">Pause communication with this IP?</h2></header><p id="caution-ip" class="caution-ip"></p><p id="caution-effect"></p><div class="caution-scope"><strong>Five minutes</strong><span>Only on this computer</span></div><h3>What could be interrupted</h3><p>All applications using this address may lose connectivity, including shared cloud services, sign-in, sync or downloads.</p><ul id="caution-services"></ul><p id="caution-unknowns">Dependencies and the person behind an address may be unknown. A VPN or proxy may hide the original source.</p><p id="caution-recovery">The managed kernel timeout expires automatically. Use Release to remove this managed block early; a receipt is required to confirm the result.</p><label class="caution-ack"><input id="caution-ack" type="checkbox"> <span>I understand this may interrupt legitimate connections on this PC.</span></label><p id="caution-expiry" role="status"></p><div class="caution-actions"><button type="button" id="caution-cancel">Cancel</button><button type="button" id="caution-confirm" disabled>Contain for 5 minutes</button></div></form>
</dialog>
'''


def compose_findings(html: str) -> str:
    """One authoritative workbench, with established IDs retained for readers."""
    html, legacy = _take(html, 'workspace-findings')
    # The old heading is now the workbench heading; preserve all other IDs once.
    import re
    legacy = re.sub(r'^<section[^>]*>', '<div class="fw-legacy" inert>', legacy)
    legacy = legacy.rsplit('</section>', 1)[0] + '</div>'
    legacy = re.sub(r'<h2 id="room-findings-title"[^>]*>.*?</h2>', '', legacy, count=1, flags=re.S)
    legacy = legacy.replace('<p>Fixed detector results linked to the qualified event set. A finding is a reason to review, not proof of malware.</p>', '')
    html = html.replace('  <noscript>', FINDINGS_HTML.replace('__LEGACY_FINDINGS__', legacy) + '  <noscript>', 1)
    html = html.replace('</body>', CAUTION_HTML + '</body>', 1)
    return html.replace('href="#pattern-reviews">Review activity', 'href="#room-findings-title">Review activity')


